<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest\SnippetVersionAllowController;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest\SnippetVersionListController;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest\SnippetVersionCreateController;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest\SnippetVersionRetrieveController;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest\SnippetVersionUpdateController;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest\SnippetVersionDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Service\Visibility\SnippetVersionRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Policy\Filter\TenantAccessible;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driven\SnippetVersionCommandRepositoryAdapter;
use Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driven\SnippetVersionQueryRepositoryAdapter;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionQueryRepositoryGateway;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\Gateway\SnippetVersionCommandRepositoryGateway;

class SnippetVersionPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[SnippetVersionQueryRepositoryGateway::class] = \DI\autowire(SnippetVersionQueryRepositoryAdapter::class);
        $def[SnippetVersionCommandRepositoryGateway::class] = \DI\autowire(SnippetVersionCommandRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/snippet-versions', [$this, 'setRoutesForSnippetVersion']);
        $collector->group('/api/me/acl/document/snippet-versions', [$this, 'setRoutesForSnippetVersionAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(SnippetVersionRestrictFilterToVisibility::class, TenantAccessible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("snippet-version", "list", "READ");
            $handler->registerResourceAction("snippet-version", "create", "WRITE");
            $handler->registerResourceAction("snippet-version", "retrieve", "READ");
            $handler->registerResourceAction("snippet-version", "update", "WRITE");
            $handler->registerResourceAction("snippet-version", "delete", "WRITE");

            $handler->registerResourceAttribute("snippet-version", "snippet", "MANAGE");
            $handler->registerResourceAttribute("snippet-version", "locale", "MANAGE");
            $handler->registerResourceAttribute("snippet-version", "subject", "MANAGE");
            $handler->registerResourceAttribute("snippet-version", "contentHtml", "MANAGE");
            $handler->registerResourceAttribute("snippet-version", "contentText", "MANAGE");
            $handler->registerResourceAttribute("snippet-version", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForSnippetVersionAcl(RouteCollectorProxy $snippetVersionGroup): void
    {
        $snippetVersionGroup->get('', [SnippetVersionAllowController::class, 'genericAllow']);
        $snippetVersionGroup->get('/{uid}', [SnippetVersionAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForSnippetVersion(RouteCollectorProxy $snippetVersionGroup): void
    {
        $snippetVersionGroup->get('', [SnippetVersionListController::class, 'list']);
        $snippetVersionGroup->post('', [SnippetVersionCreateController::class, 'create']);
        $snippetVersionGroup->get('/{uid}', [SnippetVersionRetrieveController::class, 'retrieve']);
        $snippetVersionGroup->put('/{uid}', [SnippetVersionUpdateController::class, 'update']);
        $snippetVersionGroup->delete('/{uid}', [SnippetVersionDeleteController::class, 'delete']);
        $snippetVersionGroup->delete('', [SnippetVersionDeleteController::class, 'deleteAllForQuery']);
        $snippetVersionGroup->get('/~/delete-status/{uid}', [SnippetVersionDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
